"use client";

import { useEffect, useMemo, useState } from "react";
import {
  Activity, AlertCircle, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, CalendarDays,
  Check, CheckCircle2, ChevronDown, ChevronRight, ClipboardList, Clock3, Construction,
  FileText, Filter, HardHat, Home, LayoutDashboard, LogOut, Menu, MessageSquare,
  Package, Plus, Search, Settings, ShieldCheck, Users, X, Camera, MapPin, MoreHorizontal,
  Truck, ClipboardCheck, ChartNoAxesCombined, FolderKanban, CircleHelp, Send, Eye,
  CalendarCheck, ListChecks, UserRound, Warehouse, Flag, FilePlus2, SlidersHorizontal,
  Mail, LockKeyhole, Building2, Phone
} from "lucide-react";

type Role = "Site Captain" | "Project Lead" | "Admin";
type Screen =
  | "today" | "log" | "update" | "materials" | "attendance" | "issue" | "feed" | "inbox"
  | "plhome" | "review" | "plan" | "stages" | "stage" | "create" | "check" | "chain" | "rules";

type Stage = { id: number; name: string; start: number; duration: number; gate: boolean; steps: { name: string; state: "approved" | "waiting" | "todo" }[]; docs: { name: string; status: string }[] };
type QueueItem = { id: number; kind: string; stage: string; by: string; time: string; status: "Pending" | "Approved" | "Returned"; flags: string[]; detail: string };

const initialStages: Stage[] = [
  { id: 1, name: "Site preparation", start: 0, duration: 14, gate: false, steps: [{name:"Site clearing",state:"approved"},{name:"Survey and setting out",state:"approved"},{name:"Temporary facilities",state:"waiting"},{name:"Excavation preparation",state:"todo"}], docs:[{name:"Site survey",status:"Approved"},{name:"Method statement",status:"Waiting"}] },
  { id: 2, name: "Substructure", start: 14, duration: 28, gate: true, steps: [{name:"Excavation",state:"approved"},{name:"Blinding concrete",state:"waiting"},{name:"Footings reinforcement",state:"todo"},{name:"Foundation concrete",state:"todo"}], docs:[{name:"Structural drawings",status:"Approved"},{name:"Concrete test report",status:"Missing"}] },
  { id: 3, name: "Superstructure", start: 42, duration: 45, gate: true, steps: [{name:"Columns",state:"todo"},{name:"Beams",state:"todo"},{name:"Slab formwork",state:"todo"},{name:"Concrete pour",state:"todo"}], docs:[{name:"Shop drawings",status:"Missing"},{name:"Inspection request",status:"Missing"}] },
  { id: 4, name: "Roofing and enclosure", start: 87, duration: 30, gate: false, steps: [{name:"Roof structure",state:"todo"},{name:"Roof covering",state:"todo"},{name:"External walls",state:"todo"}], docs:[{name:"Material approval",status:"Waiting"}] },
  { id: 5, name: "MEP installation", start: 117, duration: 35, gate: false, steps: [{name:"Electrical first fix",state:"todo"},{name:"Plumbing first fix",state:"todo"},{name:"HVAC installation",state:"todo"}], docs:[{name:"MEP coordination",status:"Missing"}] }
];
const initialQueue: QueueItem[] = [
  {id:101,kind:"Stage update",stage:"Site preparation",by:"Aminu Bello",time:"Today, 10:42 AM",status:"Pending",flags:[],detail:"Three work steps submitted for review with site photos."},
  {id:102,kind:"Daily log",stage:"Substructure",by:"Aminu Bello",time:"Today, 9:18 AM",status:"Pending",flags:[],detail:"Daily site report: weather, workforce and work completed."},
  {id:103,kind:"Material request",stage:"Substructure",by:"Aminu Bello",time:"Yesterday, 4:30 PM",status:"Pending",flags:["High value"],detail:"Request for 120 bags of cement for foundation works."},
  {id:104,kind:"Issue",stage:"Site preparation",by:"Aminu Bello",time:"Yesterday, 2:05 PM",status:"Pending",flags:["Urgent"],detail:"Water accumulation observed near excavation area."}
];
const navGroups = [
  {label:"WORKSPACE", items:[["today","Today",Home],["feed","Site feed",Activity],["inbox","Inbox",Bell]]},
  {label:"SITE OPERATIONS", items:[["log","Daily log",ClipboardList],["update","Stage update",ListChecks],["materials","Materials",Package],["attendance","Attendance",Users],["issue","Report an issue",AlertCircle]]},
  {label:"PROJECT CONTROL", items:[["plhome","Review queue",ClipboardCheck],["plan","Project plan",ChartNoAxesCombined],["stages","Stages",FolderKanban]]},
  {label:"ADMINISTRATION", items:[["create","Create plan",FilePlus2],["chain","Approval chain",ShieldCheck],["rules","Reporting rules",SlidersHorizontal]]}
] as const;

function cn(...v: (string|false|undefined)[]) { return v.filter(Boolean).join(" "); }
function Badge({children, tone="gray"}:{children:React.ReactNode;tone?:"green"|"amber"|"red"|"gray"}) { return <span className={`badge badge-${tone}`}>{children}</span>; }
function Button({children,onClick,kind="primary",disabled=false}:{children:React.ReactNode;onClick?:()=>void;kind?:"primary"|"secondary"|"danger";disabled?:boolean}) { return <button disabled={disabled} onClick={onClick} className={cn("btn",kind==="primary"?"btn-primary":kind==="danger"?"btn-danger":"btn-secondary",disabled&&"opacity-40 cursor-not-allowed")}>{children}</button>; }
function Card({children,className=""}:{children:React.ReactNode;className?:string}) { return <section className={`panel ${className}`}>{children}</section>; }
function SectionTitle({eyebrow,title,sub,action}:{eyebrow?:string;title:string;sub?:string;action?:React.ReactNode}) { return <div className="flex items-start justify-between gap-3 mb-5"><div>{eyebrow&&<div className="eyebrow mb-1">{eyebrow}</div>}<h2 className="text-xl font-extrabold tracking-tight" style={{fontFamily:"Manrope"}}>{title}</h2>{sub&&<p className="text-xs text-gray-500 mt-1">{sub}</p>}</div>{action}</div>; }
function Stat({label,value,change,icon:Icon}:{label:string;value:string;change:string;icon:any}) { return <Card className="p-4"><div className="flex items-center justify-between"><span className="text-xs text-gray-500 font-semibold">{label}</span><span className="rounded-lg bg-[#f0f4f1] p-2 text-[#557563]"><Icon size={16}/></span></div><div className="stat-number mt-2">{value}</div><div className="text-[10px] text-gray-500 mt-1">{change}</div></Card>; }

export default function OnSiteApp() {
  const [role,setRole] = useState<Role>("Site Captain");
  const [screen,setScreen] = useState<Screen>("today");
  const [stages,setStages] = useState<Stage[]>(initialStages);
  const [queue,setQueue] = useState<QueueItem[]>(initialQueue);
  const [selectedStage,setSelectedStage] = useState(1);
  const [selectedQueue,setSelectedQueue] = useState(101);
  const [toast,setToast] = useState("");
  const [captureOpen,setCaptureOpen] = useState(false);
  const [modal,setModal] = useState<"sendback"|"newstage"|null>(null);
  const [returnReason,setReturnReason] = useState("Photo unclear");
  const [returnNote,setReturnNote] = useState("");
  const [materialTab,setMaterialTab] = useState("Request");
  const [cement,setCement] = useState(86);
  const [quantity,setQuantity] = useState(20);
  const [attendance,setAttendance] = useState(["Musa Ibrahim","John Okafor","Peter James","Sani Umar"]);
  const [rules,setRules] = useState({daily:true,photos:true,weekly:false,stepPhoto:true,materials:true});
  const [photoCount,setPhotoCount] = useState(2);
  const [search,setSearch] = useState("");
  const [mobileMenu,setMobileMenu] = useState(false);
  const [newStageName,setNewStageName] = useState("");
  const [logText,setLogText] = useState("Completed excavation marking and prepared reinforcement materials.");
  const [issueText,setIssueText] = useState("");
  const [activeTab,setActiveTab] = useState("Overview");
  const [authView,setAuthView] = useState<"login"|"register">("login");
  const [authenticated,setAuthenticated] = useState(false);
  const [authName,setAuthName] = useState("Aminu Bello");
  const [authEmail,setAuthEmail] = useState("");
  const [authPassword,setAuthPassword] = useState("");
  const [registerName,setRegisterName] = useState("");
  const [registerEmail,setRegisterEmail] = useState("");
  const [registerPhone,setRegisterPhone] = useState("");
  const [registerCompany,setRegisterCompany] = useState("");
  const [authRole,setAuthRole] = useState<Role>("Site Captain");
  const [authNotice,setAuthNotice] = useState("");

  useEffect(()=>{ const saved=localStorage.getItem("onsite-demo-state"); if(saved){try{const d=JSON.parse(saved); if(d.stages)setStages(d.stages);if(d.queue)setQueue(d.queue);if(typeof d.cement==="number")setCement(d.cement);}catch{}} },[]);
  useEffect(()=>{ localStorage.setItem("onsite-demo-state",JSON.stringify({stages,queue,cement})); },[stages,queue,cement]);
  const notify=(message:string)=>{setToast(message);window.setTimeout(()=>setToast(""),2600);};
  const go=(s:Screen)=>{setScreen(s);setCaptureOpen(false);setMobileMenu(false);};
  const currentStage=stages.find(s=>s.id===selectedStage)??stages[0];
  const pending=queue.filter(q=>q.status==="Pending");
  const progress=(s:Stage)=>Math.round(s.steps.filter(x=>x.state==="approved").length/s.steps.length*100);
  const selectedItem=queue.find(q=>q.id===selectedQueue)??queue[0];

  const approve=(id:number)=>{setQueue(q=>q.map(x=>x.id===id?{...x,status:"Approved"}:x)); if(selectedItem?.id===id&&selectedItem.kind==="Stage update"){setStages(prev=>prev.map(s=>s.name===selectedItem.stage?{...s,steps:s.steps.map(x=>x.state==="waiting"?{...x,state:"approved"}:x)}:s));} notify("Item approved. Demo workflow updated.");};
  const sendBack=()=>{setQueue(q=>q.map(x=>x.id===selectedQueue?{...x,status:"Returned",detail:`${returnReason}${returnNote?`: ${returnNote}`:""}`}:x));setModal(null);notify("Item returned to Site Captain.");};
  const submitQueue=(kind:string,detail:string,flags:string[]=[])=>{const id=Date.now();setQueue(q=>[{id,kind,stage:currentStage.name,by:"Aminu Bello",time:"Just now",status:"Pending",flags,detail},...q]);notify(`${kind} submitted to the review queue.`);};
  const toggleStep=(stageId:number,index:number)=>setStages(prev=>prev.map(s=>s.id===stageId?{...s,steps:s.steps.map((st,i)=>i===index?{...st,state:st.state==="todo"?"waiting":st.state==="waiting"?"todo":"approved"}:st)}:s));
  const filteredQueue=queue.filter(q=>`${q.kind} ${q.stage} ${q.by}`.toLowerCase().includes(search.toLowerCase()));
  const pageTitle:Record<Screen,string>={today:"Today",log:"Daily log",update:"Stage update",materials:"Materials",attendance:"Attendance",issue:"Report an issue",feed:"Site feed",inbox:"Inbox",plhome:"Review queue",review:"Review submission",plan:"Project plan",stages:"Stages",stage:"Stage details",create:"Create project plan",check:"Check before saving",chain:"Approval chain",rules:"Reporting rules"};

  const nav = <div className="flex-1 overflow-y-auto px-3 pb-5">{navGroups.map(group=><div key={group.label} className="mt-6"><div className="px-3 mb-2 text-[9px] font-bold tracking-[.16em] text-[#73847b]">{group.label}</div>{group.items.map(([key,label,Icon])=><button key={key} onClick={()=>go(key as Screen)} className={cn("nav-item",screen===key&&"active")}><Icon size={16}/><span>{label}</span>{key==="inbox"&&<span className="ml-auto rounded-full bg-[#c78d48] px-1.5 py-0.5 text-[9px] text-white">3</span>}</button>)}</div>)}</div>;

  const renderToday=()=> <div className="space-y-5">
    <div className="flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">THURSDAY, 12 NOVEMBER 2026 · LAGOS PROJECT</div><h1 className="text-2xl font-extrabold tracking-tight mt-1" style={{fontFamily:"Manrope"}}>Good morning, {authName.split(" ")[0]} <span>☀️</span></h1><p className="text-sm text-gray-500 mt-1">Here&apos;s what&apos;s happening on site today.</p></div><Button onClick={()=>setCaptureOpen(true)}><Plus size={15}/> Capture update</Button></div>
    <div className="grid grid-cols-2 xl:grid-cols-4 gap-3"><Stat label="Project progress" value="18%" change="Based on approved work steps" icon={ChartNoAxesCombined}/><Stat label="Workers on site" value={`${attendance.length}`} change="Attendance recorded today" icon={Users}/><Stat label="Pending reviews" value={`${pending.length}`} change="Awaiting project lead" icon={ClipboardCheck}/><Stat label="Cement in store" value={`${cement} bags`} change="Available stock balance" icon={Warehouse}/></div>
    {queue.some(q=>q.status==="Returned")&&<Card className="p-4 border-l-4 border-l-[#c66c54]"><div className="flex gap-3"><AlertCircle className="text-[#bd604b]" size={19}/><div className="flex-1"><div className="font-bold text-sm">Fix this · Update returned</div><p className="text-xs text-gray-500 mt-1">{queue.find(q=>q.status==="Returned")?.detail}</p><button onClick={()=>go("update")} className="text-xs font-bold text-[#527461] mt-2">Review and resubmit <ArrowRight className="inline" size={12}/></button></div></div></Card>}
    <div className="grid lg:grid-cols-[1.45fr_1fr] gap-4">
      <Card className="p-5"><div className="flex justify-between items-start"><div><div className="eyebrow">CURRENT STAGE</div><h3 className="font-extrabold text-lg mt-1"> {currentStage.name}</h3><p className="text-xs text-gray-500 mt-1">Stage {currentStage.id} of {stages.length} · In progress</p></div><Badge tone="green">Active</Badge></div><div className="mt-5 flex justify-between text-xs mb-2"><span className="text-gray-500">Approved progress</span><b>{progress(currentStage)}%</b></div><div className="progress-track"><div className="progress-fill" style={{width:`${progress(currentStage)}%`}}/></div><div className="mt-5 space-y-3">{currentStage.steps.map((st,i)=><div key={st.name} className="flex items-center gap-3 text-xs"><span className={cn("w-5 h-5 rounded-full flex items-center justify-center",st.state==="approved"?"bg-[#e5f1e9] text-[#4d7c5c]":"bg-gray-100 text-gray-400")}>{st.state==="approved"?<Check size={12}/>:i+1}</span><span className={cn("flex-1",st.state==="approved"&&"text-gray-400 line-through")}>{st.name}</span><Badge tone={st.state==="approved"?"green":st.state==="waiting"?"amber":"gray"}>{st.state==="waiting"?"In review":st.state==="approved"?"Approved":"To do"}</Badge></div>)}</div><div className="mt-5 pt-4 border-t border-gray-100 flex justify-between"><button onClick={()=>{setSelectedStage(currentStage.id);go("update")}} className="text-xs font-bold text-[#4c715d]">Update stage <ArrowRight className="inline" size={13}/></button><button onClick={()=>{setSelectedStage(currentStage.id);go("stage")}} className="text-xs text-gray-500">View details</button></div></Card>
      <Card className="p-5"><div className="flex justify-between items-center"><h3 className="font-bold text-sm">Reports due today</h3><Badge tone="amber">2 due</Badge></div><div className="mt-4 space-y-4">{[{name:"Daily site log",desc:"Weather, workforce and completed work",done:false},{name:"Site photos",desc:`${photoCount} of 4 photos captured`,done:false},{name:"Material count",desc:"End-of-day store reconciliation",done:true}].filter((_,i)=>i!==2||rules.materials).map((x,i)=><div key={x.name} className="flex items-start gap-3"><div className={cn("rounded-lg p-2",x.done?"bg-green-50 text-green-700":"bg-[#f4f2ed] text-[#987a45]")}>{x.done?<CheckCircle2 size={16}/>:<ClipboardList size={16}/>}</div><div className="flex-1"><div className="text-xs font-bold">{x.name}</div><div className="text-[10px] text-gray-500 mt-1">{x.desc}</div></div><button onClick={()=>go(i===0?"log":i===1?"feed":"materials")} className="text-[10px] font-bold text-[#547563]">{x.done?"View":"Start"}</button></div>)}</div><div className="mt-5 pt-4 border-t border-gray-100"><div className="flex justify-between text-[10px] text-gray-500"><span>Daily compliance</span><b>2 / 3 complete</b></div><div className="progress-track mt-2"><div className="progress-fill" style={{width:"67%"}}/></div></div></Card>
    </div>
    <Card className="p-5"><div className="flex justify-between items-center mb-3"><h3 className="font-bold text-sm">Expected deliveries</h3><button onClick={()=>{setMaterialTab("Receive");go("materials")}} className="text-xs font-bold text-[#547563]">View materials</button></div><div className="flex items-center gap-3"><div className="rounded-lg bg-[#f3f5f3] p-3"><Truck size={19}/></div><div className="flex-1"><div className="text-xs font-bold">Cement · 200 bags</div><div className="text-[10px] text-gray-500 mt-1">Supplier: BuildRight Materials · Expected today</div></div><Badge tone="amber">Awaiting receipt</Badge><Button kind="secondary" onClick={()=>{setMaterialTab("Receive");go("materials")}}>Confirm</Button></div></Card>
  </div>;

  const renderLog=()=> <div className="max-w-3xl space-y-4"><SectionTitle eyebrow="SITE CAPTAIN · DAILY REPORT" title="Daily site log" sub="Record what happened on site today."/><Card className="p-5 space-y-4"><div className="grid sm:grid-cols-2 gap-4"><div><label className="label">Weather conditions</label><select className="field"><option>Sunny</option><option>Cloudy</option><option>Rainy</option><option>Overcast</option></select></div><div><label className="label">Workers on site</label><input className="field" type="number" defaultValue={attendance.length}/></div></div><div><label className="label">Work completed</label><textarea className="field min-h-28" value={logText} onChange={e=>setLogText(e.target.value)}/></div><div><label className="label">Site photos · {photoCount} of 4 minimum target</label><div className="flex gap-2 flex-wrap"><div className="rounded-lg border border-dashed border-gray-300 bg-gray-50 p-4 text-center flex-1 min-w-28"><Camera className="mx-auto text-gray-400" size={20}/><div className="text-[10px] text-gray-500 mt-2">Demo photo evidence</div></div><Button kind="secondary" onClick={()=>setPhotoCount(n=>Math.min(4,n+1))}><Plus size={14}/> Add photo</Button></div></div><div><label className="label">Issues or delays</label><textarea className="field" placeholder="Describe any issues encountered..."/></div><div className="flex justify-end gap-2"><Button kind="secondary" onClick={()=>notify("Draft saved in this browser.")}>Save draft</Button><Button onClick={()=>submitQueue("Daily log",logText)}>Submit daily log <Send size={13}/></Button></div></Card><p className="text-[10px] text-gray-400">Prototype note: photo tiles are placeholders. Production evidence requires in-app capture, trusted timestamps, GPS validation and secure upload.</p></div>;

  const renderUpdate=()=> <div className="max-w-3xl space-y-4"><SectionTitle eyebrow="SITE CAPTAIN · WORK PROGRESS" title="Stage update" sub="Tick completed steps. Newly completed steps enter the approval workflow."/><Card className="p-5"><label className="label">Select stage</label><select className="field max-w-sm" value={selectedStage} onChange={e=>setSelectedStage(Number(e.target.value))}>{stages.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><div className="mt-5 divide-y divide-gray-100">{currentStage.steps.map((st,i)=><label key={st.name} className="flex items-center gap-3 py-3 cursor-pointer"><input type="checkbox" checked={st.state!=="todo"} disabled={st.state==="approved"} onChange={()=>toggleStep(currentStage.id,i)} className="w-4 h-4 accent-[#456b56]"/><span className="flex-1 text-sm">{st.name}</span><Badge tone={st.state==="approved"?"green":st.state==="waiting"?"amber":"gray"}>{st.state==="approved"?"Approved":st.state==="waiting"?"Ready for review":"Not started"}</Badge>{st.state==="waiting"&&<button type="button" onClick={()=>notify("Evidence camera is simulated in this prototype.")} className="text-xs text-[#547563]"><Camera size={15}/></button>}</label>)}</div><div className="mt-4 rounded-lg bg-[#f6f7f6] p-3 text-xs text-gray-600"><b>Evidence requirement:</b> Each newly ticked step requires a photo when the reporting rule is enabled. This demo uses placeholder evidence.</div><div className="flex justify-end mt-5"><Button onClick={()=>submitQueue("Stage update",`${currentStage.name}: completed steps submitted for review.`)}>Submit for approval <ArrowRight size={14}/></Button></div></Card></div>;

  const renderMaterials=()=> <div className="space-y-4"><SectionTitle eyebrow="SITE OPERATIONS" title="Materials" sub="Track requests, deliveries and store issues." action={<Badge tone="green">Demo inventory</Badge>}/><div className="grid sm:grid-cols-3 gap-3"><Stat label="Cement balance" value={`${cement} bags`} change="Current demo stock" icon={Warehouse}/><Stat label="Pending requests" value="2" change="Awaiting approval" icon={ClipboardList}/><Stat label="Expected deliveries" value="200" change="Bags expected today" icon={Truck}/></div><div className="flex gap-2 border-b border-gray-200">{["Request","Receive","Issue out"].map(t=><button key={t} onClick={()=>setMaterialTab(t)} className={cn("px-4 py-2 text-xs font-bold border-b-2",materialTab===t?"border-[#53745f] text-[#456b56]":"border-transparent text-gray-500")}>{t}</button>)}</div><Card className="p-5 max-w-2xl">{materialTab==="Request"?<><h3 className="font-bold text-sm mb-4">Request materials</h3><div className="space-y-3"><div><label className="label">Material</label><select className="field"><option>Cement (50kg bag)</option><option>Reinforcement steel</option><option>Sand</option><option>Aggregate</option></select></div><div className="grid sm:grid-cols-2 gap-3"><div><label className="label">Quantity</label><input className="field" type="number" defaultValue="120"/></div><div><label className="label">Needed by</label><input className="field" type="date" defaultValue="2026-11-14"/></div></div><div><label className="label">Linked work item</label><select className="field"><option>Foundation works</option><option>Blinding concrete</option></select></div><div className="flex justify-end"><Button onClick={()=>submitQueue("Material request","120 bags of cement requested for foundation works.")}>Send request</Button></div></div></>:materialTab==="Receive"?<><h3 className="font-bold text-sm mb-4">Confirm delivery</h3><div className="rounded-lg bg-[#f6f7f6] p-3 mb-4 text-xs"><b>Expected delivery: 200 bags cement</b><p className="text-gray-500 mt-1">BuildRight Materials · Waybill required in production</p></div><label className="label">Quantity received</label><input className="field mb-4" type="number" value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/><div className="flex justify-end"><Button onClick={()=>{setCement(c=>c+quantity);notify(`${quantity} bags added to demo inventory.`)}}>Confirm receipt</Button></div></>:<><h3 className="font-bold text-sm mb-4">Issue materials out</h3><p className="text-xs text-gray-500 mb-3">Available balance: <b>{cement} bags</b></p><label className="label">Quantity to issue</label><input className="field mb-3" type="number" min="1" max={cement} value={quantity} onChange={e=>setQuantity(Number(e.target.value))}/><label className="label">Received by</label><input className="field mb-4" defaultValue="Musa Ibrahim"/><div className="flex justify-end"><Button disabled={quantity<1||quantity>cement} onClick={()=>{setCement(c=>c-quantity);notify(`${quantity} bags issued from demo inventory.`)}}>Record issue</Button></div></>}</Card></div>;

  const renderAttendance=()=> <div className="space-y-4"><SectionTitle eyebrow="SITE OPERATIONS" title="Attendance" sub="Manage today's workforce check-in." action={<Button onClick={()=>notify("Selfie check-in is a simulated feature.")}><Camera size={14}/> Selfie check-in</Button>}/><div className="grid sm:grid-cols-3 gap-3"><Stat label="Present today" value={`${attendance.length}`} change="Workers checked in" icon={Users}/><Stat label="Expected" value="18" change="Scheduled workforce" icon={CalendarCheck}/><Stat label="Attendance rate" value={`${Math.round(attendance.length/18*100)}%`} change="Based on expected workers" icon={ChartNoAxesCombined}/></div><Card className="p-5"><div className="flex justify-between mb-4"><h3 className="font-bold text-sm">Site workforce</h3><Button kind="secondary" onClick={()=>setAttendance(a=>[...a,"New worker "+(a.length+1)])}><Plus size={13}/> Add worker</Button></div>{["Musa Ibrahim","John Okafor","Peter James","Sani Umar","David Eze","Emeka Nwosu"].map((name,i)=><div key={name} className="table-row flex items-center py-3 gap-3"><div className="w-8 h-8 rounded-full bg-[#edf2ee] text-[#567461] flex items-center justify-center text-xs font-bold">{name.split(" ").map(x=>x[0]).join("")}</div><div className="flex-1"><div className="text-xs font-bold">{name}</div><div className="text-[10px] text-gray-500">{["Mason","Electrician","Carpenter","General labour","Plumber","Steel fixer"][i]}</div></div>{attendance.includes(name)?<><Badge tone="green">Checked in · 7:4{i} AM</Badge><button onClick={()=>setAttendance(a=>a.filter(x=>x!==name))} className="text-[10px] text-gray-400">Undo</button></>:<Button kind="secondary" onClick={()=>setAttendance(a=>[...a,name])}>Mark present</Button>}</div>)}</Card></div>;

  const renderIssue=()=> <div className="max-w-2xl space-y-4"><SectionTitle eyebrow="SITE OPERATIONS" title="Report an issue" sub="Raise a site issue for the project team."/><Card className="p-5 space-y-4"><div><label className="label">Issue title</label><input className="field" placeholder="e.g. Water accumulation near excavation" value={issueText} onChange={e=>setIssueText(e.target.value)}/></div><div><label className="label">Description</label><textarea className="field min-h-28" placeholder="Describe what happened, where and any immediate action taken."/></div><div className="grid sm:grid-cols-2 gap-3"><div><label className="label">Urgency</label><select className="field"><option>Normal</option><option>High</option><option>Urgent</option></select></div><div><label className="label">Location</label><div className="field flex items-center gap-2 text-gray-500"><MapPin size={14}/> Site location (demo)</div></div></div><button onClick={()=>notify("Photo capture is simulated in this prototype.")} className="w-full rounded-lg border border-dashed border-gray-300 p-5 text-center text-xs text-gray-500"><Camera className="mx-auto mb-2" size={20}/>Attach issue photo</button><div className="flex justify-end"><Button disabled={!issueText.trim()} onClick={()=>{submitQueue("Issue",issueText,["Urgent"]);setIssueText("");}}>Report issue</Button></div></Card></div>;

  const renderFeed=()=> <div className="space-y-4"><SectionTitle eyebrow="PROJECT ACTIVITY" title="Site feed" sub="Updates and evidence shared across the project."/><div className="grid lg:grid-cols-[1fr_280px] gap-4"><div className="space-y-3">{[{name:"Aminu Bello",role:"Site Captain",time:"Today · 10:42 AM",text:"Site preparation update submitted. Survey and setting out completed; temporary facilities are ready for inspection.",tag:"Awaiting approval"},{name:"Musa Ibrahim",role:"Foreman",time:"Today · 9:10 AM",text:"Morning toolbox talk completed with the foundation team. Work area inspected before excavation activities.",tag:"Approved"},{name:"Aminu Bello",role:"Site Captain",time:"Yesterday · 4:35 PM",text:"Material request raised for cement required for upcoming foundation works.",tag:"In review"}].map((p,i)=><Card key={i} className="p-4"><div className="flex items-center gap-3"><div className="w-9 h-9 rounded-full bg-[#eaf0ec] flex items-center justify-center text-xs font-bold text-[#557260]">{p.name.split(" ").map(x=>x[0]).join("")}</div><div className="flex-1"><div className="text-xs font-bold">{p.name}</div><div className="text-[10px] text-gray-500">{p.role} · {p.time}</div></div><Badge tone={p.tag==="Approved"?"green":"amber"}>{p.tag}</Badge></div><p className="text-xs text-gray-700 leading-6 mt-3">{p.text}</p><div className="mt-3 h-32 rounded-lg bg-gradient-to-br from-[#e8ece8] to-[#d4ddd6] flex items-center justify-center text-[#8a9b90]"><Construction size={32}/><span className="text-[10px] ml-2">Demo site evidence</span></div><div className="flex gap-4 mt-3 text-[10px] text-gray-500"><span><MessageSquare className="inline mr-1" size={12}/>2 comments</span><span><Eye className="inline mr-1" size={12}/>Project team</span></div></Card>)}</div><Card className="p-4 h-fit"><h3 className="font-bold text-sm">Project stories</h3><div className="mt-4 space-y-3">{stages.slice(0,4).map((s,i)=><div key={s.id} className="flex gap-3 items-center"><div className="w-10 h-10 rounded-lg bg-[#e9efeb] flex items-center justify-center text-[#597766]"><Construction size={17}/></div><div><div className="text-xs font-bold">{s.name}</div><div className="text-[10px] text-gray-500">{progress(s)}% approved</div></div></div>)}</div></Card></div></div>;

  const renderInbox=()=> <div className="space-y-4"><SectionTitle eyebrow="NOTIFICATIONS" title="Inbox" sub="Updates that need your attention."/><Card className="p-2">{[{title:"Stage update submitted",sub:"Site preparation · Aminu Bello",time:"10:42 AM",icon:ClipboardCheck},{title:"Material request awaiting approval",sub:"120 bags cement · Substructure",time:"Yesterday",icon:Package},{title:"Daily log reminder",sub:"Your daily report is due today",time:"Yesterday",icon:Bell},{title:"Issue reported",sub:"Water accumulation near excavation",time:"Nov 10",icon:AlertCircle}].map((x,i)=><div key={i} className="flex gap-3 p-3 border-b last:border-0 border-gray-100"><div className="rounded-lg bg-[#f0f4f1] text-[#597665] p-2 h-fit"><x.icon size={16}/></div><div className="flex-1"><div className="text-xs font-bold">{x.title}</div><div className="text-[10px] text-gray-500 mt-1">{x.sub}</div></div><span className="text-[10px] text-gray-400">{x.time}</span></div>)}</Card></div>;

  const renderQueue=()=> <div className="space-y-4"><SectionTitle eyebrow="PROJECT LEAD" title="Review queue" sub="Review submissions and keep site work moving."/><div className="grid sm:grid-cols-3 gap-3"><Stat label="To review" value={`${pending.length}`} change="Awaiting your action" icon={ClipboardCheck}/><Stat label="Overdue" value="1" change="Past review target" icon={Clock3}/><Stat label="Approved today" value={`${queue.filter(q=>q.status==="Approved").length}`} change="Across this project" icon={CheckCircle2}/></div><Card className="p-4"><div className="flex flex-wrap gap-2 justify-between mb-4"><h3 className="font-bold text-sm">Submissions</h3><div className="flex gap-2"><div className="relative"><Search size={13} className="absolute left-3 top-2.5 text-gray-400"/><input className="field pl-8 py-2 w-48" placeholder="Search queue" value={search} onChange={e=>setSearch(e.target.value)}/></div><Button kind="secondary"><Filter size={13}/> Filter</Button></div></div>{filteredQueue.map(q=><div key={q.id} className="table-row py-4 flex items-center gap-3"><div className="w-9 h-9 rounded-lg bg-[#f0f3f0] flex items-center justify-center text-[#587563]"><ClipboardCheck size={17}/></div><div className="flex-1 min-w-0"><div className="text-xs font-bold">{q.kind} <span className="text-gray-400 font-normal">· {q.stage}</span></div><div className="text-[10px] text-gray-500 mt-1">{q.by} · {q.time}</div>{q.flags.map(f=><Badge key={f} tone="red">{f}</Badge>)}</div><Badge tone={q.status==="Approved"?"green":q.status==="Returned"?"red":"amber"}>{q.status}</Badge><button onClick={()=>{setSelectedQueue(q.id);go("review")}} className="text-xs font-bold text-[#547563]">Review <ChevronRight className="inline" size={13}/></button>{q.status==="Pending"&&<button onClick={()=>approve(q.id)} className="rounded-lg bg-[#eaf3ed] p-2 text-[#477354]" title="Approve"><Check size={15}/></button>}</div>)}</Card></div>;

  const renderReview=()=> <div className="max-w-3xl space-y-4"><button onClick={()=>go("plhome")} className="text-xs text-gray-500"><ArrowLeft className="inline mr-1" size={13}/> Back to queue</button><SectionTitle eyebrow="PROJECT LEAD · SUBMISSION REVIEW" title={selectedItem?.kind??"Review"} sub={`${selectedItem?.stage??""} · Submitted by ${selectedItem?.by??""}`}/><Card className="p-5"><div className="flex justify-between"><Badge tone="amber">{selectedItem?.status??"Pending"}</Badge><span className="text-[10px] text-gray-400">{selectedItem?.time}</span></div><p className="text-sm leading-6 mt-4">{selectedItem?.detail}</p><div className="mt-4 grid sm:grid-cols-2 gap-3"><div className="rounded-lg bg-[#f5f7f5] p-4"><div className="eyebrow">AUTOMATIC CHECK</div><div className="flex items-center gap-2 mt-2 text-xs"><CheckCircle2 size={15} className="text-green-600"/> Required fields complete</div><div className="flex items-center gap-2 mt-2 text-xs"><CheckCircle2 size={15} className="text-green-600"/> Project stage identified</div></div><div className="rounded-lg bg-[#f5f7f5] p-4"><div className="eyebrow">APPROVAL CHAIN</div><div className="text-xs mt-2">1. Project Lead <Badge tone="amber">Current</Badge></div><div className="text-xs mt-2">2. Project Director <Badge>Next</Badge></div></div></div><div className="flex flex-wrap justify-end gap-2 mt-5"><Button kind="danger" onClick={()=>setModal("sendback")}>Send back</Button><Button disabled={selectedItem?.status!=="Pending"} onClick={()=>approve(selectedQueue)}>Approve submission <Check size={14}/></Button></div></Card><p className="text-[10px] text-gray-400">Demo note: the prototype allows role simulation. Production must enforce approval identity, separation of duties and value-based routing server-side.</p></div>;

  const renderPlan=()=> <div className="space-y-4"><SectionTitle eyebrow="PROJECT LEAD" title="Project plan" sub="A high-level view of project stages and planned durations." action={<Button onClick={()=>go("create")}><Plus size={14}/> Add stage</Button>}/><Card className="p-5"><div className="flex flex-wrap justify-between gap-2 mb-5"><div><div className="text-xs font-bold">Construction programme</div><div className="text-[10px] text-gray-500 mt-1">Project start · 1 November 2026</div></div><Badge tone="green">Linked stages on</Badge></div><div className="grid grid-cols-[145px_1fr] gap-y-4 text-[10px]"><div></div><div className="grid grid-cols-5 text-gray-400"><span>Nov 1</span><span>Nov 30</span><span>Dec 30</span><span>Jan 29</span><span>Feb 28</span></div>{stages.map(s=><><div key={`n${s.id}`} className="text-xs font-semibold pr-2">{s.name}</div><div key={`b${s.id}`} className="relative h-8 bg-[#f5f6f5] rounded-md"><div className="absolute top-1 bottom-1 rounded bg-[#d9e4dc] border border-[#b7cbbd]" style={{left:`${s.start/150*100}%`,width:`${s.duration/150*100}%`}}><div className="h-full bg-[#698a76] rounded-l" style={{width:`${progress(s)}%`}}/></div></div></>)}</div><div className="mt-5 text-[10px] text-gray-400">Illustrative timeline · Dependencies and critical path are not implemented in this prototype.</div></Card></div>;

  const renderStages=()=> <div className="space-y-4"><SectionTitle eyebrow="PROJECT CONTROL" title="Stages" sub="All project stages, progress and approval gates."/><div className="space-y-3">{stages.map(s=><Card key={s.id} className="p-4"><div className="flex items-center gap-3"><div className="w-9 h-9 rounded-lg bg-[#edf2ee] text-[#557562] flex items-center justify-center font-bold text-xs">{String(s.id).padStart(2,"0")}</div><div className="flex-1"><div className="font-bold text-sm">{s.name}</div><div className="text-[10px] text-gray-500 mt-1">Day {s.start+1} · {s.duration} days · {s.steps.length} work steps</div></div>{s.gate&&<Badge tone="amber">Approval gate</Badge>}<b className="text-xs">{progress(s)}%</b><button onClick={()=>{setSelectedStage(s.id);go("stage")}} className="text-gray-400"><ChevronRight size={17}/></button></div><div className="progress-track mt-3"><div className="progress-fill" style={{width:`${progress(s)}%`}}/></div></Card>)}</div></div>;

  const renderStage=()=> <div className="space-y-4"><button onClick={()=>go("stages")} className="text-xs text-gray-500"><ArrowLeft className="inline mr-1" size={13}/> All stages</button><SectionTitle eyebrow={`STAGE ${currentStage.id} · PROJECT RECORD`} title={currentStage.name} sub={`${currentStage.duration} planned days · Starts day ${currentStage.start+1}`}/><div className="flex gap-2 border-b border-gray-200">{["Overview","Documents","Approvals","Photos","Timeline"].map(t=><button key={t} onClick={()=>setActiveTab(t)} className={cn("px-3 py-2 text-xs font-bold border-b-2",activeTab===t?"border-[#53745f] text-[#456b56]":"border-transparent text-gray-500")}>{t}</button>)}</div><Card className="p-5">{activeTab==="Overview"?<><div className="flex justify-between text-xs"><b>Approved work progress</b><b>{progress(currentStage)}%</b></div><div className="progress-track mt-2 mb-5"><div className="progress-fill" style={{width:`${progress(currentStage)}%`}}/></div>{currentStage.steps.map((s,i)=><div key={s.name} className="table-row flex py-3 items-center gap-3 text-xs"><span className="flex-1">{s.name}</span><Badge tone={s.state==="approved"?"green":s.state==="waiting"?"amber":"gray"}>{s.state}</Badge></div>)}</>:activeTab==="Documents"?currentStage.docs.map(d=><div key={d.name} className="table-row flex py-3 text-xs items-center"><FileText size={15} className="mr-2 text-gray-400"/><span className="flex-1">{d.name}</span><Badge tone={d.status==="Approved"?"green":d.status==="Waiting"?"amber":"red"}>{d.status}</Badge><button onClick={()=>notify("Document upload is simulated.")} className="ml-3 text-[#547563]">Upload</button></div>):activeTab==="Approvals"?<div className="space-y-3 text-xs"><div>Site Captain <Badge tone="green">Submitted</Badge></div><div>Project Lead <Badge tone="amber">Pending</Badge></div><div>Project Director <Badge>Upcoming</Badge></div></div>:activeTab==="Photos"?<div className="grid grid-cols-2 sm:grid-cols-3 gap-3">{[1,2,3].map(i=><div key={i} className="aspect-square rounded-lg bg-[#e9eee9] flex items-center justify-center text-[#91a296]"><Camera size={25}/></div>)}</div>:<div className="text-xs text-gray-500">No additional timeline events in the demo record.</div>}</Card>{currentStage.gate&&<div className="rounded-lg bg-[#fff7e8] border border-[#f0dfbd] p-4 text-xs text-[#87652c]"><AlertCircle size={15} className="inline mr-2"/>This stage is an approval gate. The next stage should remain blocked until approval.</div>}</div>;

  const renderCreate=()=> <div className="space-y-4"><SectionTitle eyebrow="ADMINISTRATION" title="Create project plan" sub="Start with a template or create a blank plan."/><div className="grid sm:grid-cols-2 gap-3">{["Bungalow","Duplex","4-storey block","Road project"].map((x,i)=><button key={x} onClick={()=>{setNewStageName(x+" project");go("check")}} className="panel p-5 text-left hover:border-[#9ab09f]"><div className="rounded-lg bg-[#edf2ee] p-2 w-fit text-[#557562]"><Construction size={19}/></div><div className="font-bold text-sm mt-3">{x}</div><div className="text-[10px] text-gray-500 mt-1">Use a starter stage structure</div></button>)}</div><Card className="p-5"><div className="font-bold text-sm">Start from blank</div><p className="text-xs text-gray-500 mt-1 mb-4">Create a new draft plan and add your own stages.</p><Button onClick={()=>go("check")}>Create blank plan <ArrowRight size={14}/></Button></Card><p className="text-[10px] text-gray-400">File import for Excel, MS Project and Primavera is a future integration.</p></div>;

  const renderCheck=()=> <div className="max-w-2xl space-y-4"><SectionTitle eyebrow="ADMINISTRATION · DRAFT PLAN" title="Check before saving" sub="Review the draft plan before making it active."/><Card className="p-5"><div className="flex justify-between items-center mb-4"><b className="text-sm">{newStageName||"New project plan"}</b><Badge tone="amber">Draft</Badge></div>{stages.map(s=><div key={s.id} className="table-row flex items-center py-3 gap-2 text-xs"><span className="flex-1">{s.name}</span><span className="text-gray-400">{s.duration} days</span><button onClick={()=>setStages(p=>p.filter(x=>x.id!==s.id))} className="text-gray-400"><X size={14}/></button></div>)}<div className="mt-4 flex gap-2"><input className="field" placeholder="New stage name" value={newStageName} onChange={e=>setNewStageName(e.target.value)}/><Button kind="secondary" onClick={()=>{if(newStageName.trim()){setStages(p=>[...p,{id:Math.max(0,...p.map(s=>s.id))+1,name:newStageName,start:150,duration:14,gate:false,steps:[{name:"Initial work item",state:"todo"}],docs:[]}]);setNewStageName("");notify("Stage added to draft.");}}}><Plus size={14}/> Add</Button></div><div className="flex justify-end mt-5"><Button onClick={()=>{go("plan");notify("Demo plan saved locally.")}}>Save plan</Button></div></Card></div>;

  const renderChain=()=> <div className="space-y-4"><SectionTitle eyebrow="ADMINISTRATION" title="Approval chain" sub="Define who reviews project submissions and in what order."/><Card className="p-5"><div className="flex justify-between items-center mb-4"><b className="text-sm">Standard project approvals</b><Badge tone="green">Sequential</Badge></div>{[{role:"Site Captain",person:"Aminu Bello",hours:4},{role:"Project Lead",person:"Chinedu Okafor",hours:24},{role:"Project Director",person:"Fatima Musa",hours:48}].map((x,i)=><div key={x.role} className="table-row flex items-center gap-3 py-4"><div className="w-8 h-8 rounded-full bg-[#edf2ee] text-[#547461] flex items-center justify-center text-xs font-bold">{i+1}</div><div className="flex-1"><div className="text-xs font-bold">{x.role}</div><div className="text-[10px] text-gray-500 mt-1">{x.person}</div></div><div className="text-right"><div className="text-xs font-bold">{x.hours}h</div><div className="text-[10px] text-gray-400">Review target</div></div><button onClick={()=>notify("Approval step settings are demo-only.")} className="text-gray-400"><MoreHorizontal size={17}/></button></div>)}<Button kind="secondary" onClick={()=>notify("New approval step editor is not implemented yet.")}><Plus size={14}/> Add approval step</Button></Card><p className="text-[10px] text-gray-400">Sequential demo chain. Parallel approvals, delegation and escalation timers are not implemented.</p></div>;

  const renderRules=()=> <div className="max-w-3xl space-y-4"><SectionTitle eyebrow="ADMINISTRATION" title="Reporting rules" sub="Choose which reports and evidence are required on site."/><Card className="p-5"><div className="space-y-1">{([{key:"daily",title:"Daily site log",desc:"Require a daily site report."},{key:"photos",title:"Site photos",desc:"Require a minimum number of site photos each day."},{key:"weekly",title:"Weekly progress report",desc:"Require a weekly project summary."},{key:"stepPhoto",title:"Photo with every step ticked",desc:"Each newly completed work step requires evidence."},{key:"materials",title:"Material count",desc:"Require material stock reconciliation."}] as const).map(r=><div key={r.key} className="table-row flex items-center gap-3 py-4"><div className="flex-1"><div className="text-xs font-bold">{r.title}</div><div className="text-[10px] text-gray-500 mt-1">{r.desc}</div></div><button onClick={()=>setRules(p=>({...p,[r.key]:!p[r.key]}))} className={cn("w-10 h-6 rounded-full p-1 transition",rules[r.key]?"bg-[#527561]":"bg-gray-300")}><span className={cn("block w-4 h-4 rounded-full bg-white transition",rules[r.key]?"translate-x-4":"translate-x-0")}/></button></div>)}</div><div className="mt-4"><label className="label">Minimum site photos per day</label><input type="number" className="field max-w-32" defaultValue={4}/></div><div className="flex justify-end mt-5"><Button onClick={()=>notify("Reporting rules saved in demo state.")}>Save rules</Button></div></Card></div>;

  const renderContent=()=> {
    switch(screen){
      case "today": return renderToday(); case "log": return renderLog(); case "update": return renderUpdate(); case "materials": return renderMaterials();
      case "attendance": return renderAttendance(); case "issue": return renderIssue(); case "feed": return renderFeed(); case "inbox": return renderInbox();
      case "plhome": return renderQueue(); case "review": return renderReview(); case "plan": return renderPlan(); case "stages": return renderStages();
      case "stage": return renderStage(); case "create": return renderCreate(); case "check": return renderCheck(); case "chain": return renderChain(); case "rules": return renderRules();
    }
  };

  const changeRole=(r:Role)=>{setRole(r);go(r==="Site Captain"?"today":r==="Project Lead"?"plhome":"rules");};
  const enterWorkspace=(name:string,r:Role)=>{
    setAuthName(name.trim() || "Aminu Bello");
    setRole(r);
    setScreen(r==="Site Captain"?"today":r==="Project Lead"?"plhome":"rules");
    setAuthenticated(true);
    setAuthPassword("");
    setAuthNotice("");
  };

  if(!authenticated) return <main className="auth-page min-h-screen flex flex-col lg:flex-row">
    <section className="auth-brand-panel relative flex flex-col justify-between p-7 sm:p-10 lg:p-14 lg:w-[48%] min-h-[310px] lg:min-h-screen overflow-hidden">
      <div className="relative z-10 flex items-center gap-3">
        <div className="w-11 h-11 rounded-xl bg-white text-[#171717] flex items-center justify-center"><Construction size={24}/></div>
        <div><div className="text-white text-2xl font-extrabold tracking-tight" style={{fontFamily:"Manrope"}}>OnSite<span className="text-gray-400">.</span></div><div className="text-[9px] tracking-[.2em] text-gray-400 font-bold">PROJECT WORKSPACE</div></div>
      </div>
      <div className="relative z-10 max-w-xl py-10 lg:py-0">
        <div className="auth-kicker"><span className="w-2 h-2 rounded-full bg-white inline-block mr-2"/> CONSTRUCTION PROJECT MANAGEMENT</div>
        <h1 className="text-4xl sm:text-5xl xl:text-6xl leading-[1.05] font-extrabold tracking-tight text-white mt-6" style={{fontFamily:"Manrope"}}>Every site.<br/>Every stage.<br/><span className="text-gray-400">In sync.</span></h1>
        <p className="text-sm sm:text-base text-gray-300 leading-7 mt-6 max-w-md">Keep your site team, project updates and approvals connected in one shared workspace.</p>
        <div className="mt-9 space-y-4 text-sm text-gray-300">
          {["Track work progress across project stages","Keep reports, photos and documents together","Move reviews and approvals forward"].map(item=><div key={item} className="flex items-center gap-3"><span className="w-6 h-6 rounded-full border border-gray-600 flex items-center justify-center"><Check size={13}/></span>{item}</div>)}
        </div>
      </div>
      <div className="relative z-10 flex items-center justify-between text-[10px] text-gray-500 tracking-wide"><span>BUILT FOR THE PEOPLE WHO BUILD.</span><span>ONSITE · PROTOTYPE</span></div>
      <div className="auth-grid-mark" aria-hidden="true"/>
    </section>

    <section className="flex-1 flex items-center justify-center px-5 py-10 sm:px-10 lg:px-14 bg-[#f5f5f4]">
      <div className="w-full max-w-[440px]">
        <div className="mb-8 lg:hidden flex items-center gap-2 text-lg font-extrabold"><span className="w-8 h-8 rounded-lg bg-[#171717] text-white flex items-center justify-center"><Construction size={17}/></span>OnSite.</div>
        <div className="mb-8"><div className="auth-kicker text-gray-500">{authView==="login"?"WELCOME BACK":"GET STARTED"}</div><h2 className="text-3xl font-extrabold tracking-tight mt-3 text-[#171717]" style={{fontFamily:"Manrope"}}>{authView==="login"?"Sign in to OnSite":"Create your account"}</h2><p className="text-sm text-gray-500 mt-2">{authView==="login"?"Access your construction project workspace.":"Set up your profile to join your project workspace."}</p></div>

        <div className="auth-card bg-white border border-gray-200 rounded-2xl p-6 sm:p-8 shadow-[0_12px_40px_rgba(0,0,0,0.04)]">
          {authView==="login"?<form onSubmit={e=>{e.preventDefault();enterWorkspace("Aminu Bello",authRole);}} className="space-y-5">
            <div><label className="auth-label" htmlFor="login-email">Email address</label><div className="auth-input-wrap"><Mail size={17}/><input id="login-email" className="auth-input" type="text" autoComplete="off" placeholder="you@company.com" value={authEmail} onChange={e=>setAuthEmail(e.target.value)}/></div></div>
            <div><div className="flex justify-between items-center"><label className="auth-label" htmlFor="login-password">Password</label><button type="button" onClick={()=>setAuthNotice("Password reset will be connected when authentication is implemented.")} className="text-[11px] font-bold text-gray-500 hover:text-black">Forgot password?</button></div><div className="auth-input-wrap"><LockKeyhole size={17}/><input id="login-password" className="auth-input" type="password" autoComplete="off" placeholder="Enter your password" value={authPassword} onChange={e=>setAuthPassword(e.target.value)}/></div></div>
            <div><label className="auth-label" htmlFor="login-role">Enter demo workspace as</label><div className="auth-input-wrap"><UserRound size={17}/><select id="login-role" className="auth-input bg-transparent" value={authRole} onChange={e=>setAuthRole(e.target.value as Role)}><option>Site Captain</option><option>Project Lead</option><option>Admin</option></select></div></div>
            {authNotice&&<p className="text-xs text-gray-500 bg-gray-100 rounded-lg p-3">{authNotice}</p>}
            <button type="submit" className="auth-submit">Sign in <ArrowRight size={16}/></button>
            <p className="text-center text-[10px] text-gray-400">Demo mode · any email and password will work</p>
          </form>:<form onSubmit={e=>{e.preventDefault();enterWorkspace(registerName,authRole);}} className="space-y-4">
            <div><label className="auth-label" htmlFor="register-name">Full name</label><div className="auth-input-wrap"><UserRound size={17}/><input id="register-name" className="auth-input" type="text" placeholder="Your full name" value={registerName} onChange={e=>setRegisterName(e.target.value)}/></div></div>
            <div><label className="auth-label" htmlFor="register-email">Work email</label><div className="auth-input-wrap"><Mail size={17}/><input id="register-email" className="auth-input" type="text" placeholder="you@company.com" value={registerEmail} onChange={e=>setRegisterEmail(e.target.value)}/></div></div>
            <div className="grid sm:grid-cols-2 gap-3"><div><label className="auth-label" htmlFor="register-phone">Phone number</label><div className="auth-input-wrap"><Phone size={16}/><input id="register-phone" className="auth-input" type="text" placeholder="+60..." value={registerPhone} onChange={e=>setRegisterPhone(e.target.value)}/></div></div><div><label className="auth-label" htmlFor="register-company">Company</label><div className="auth-input-wrap"><Building2 size={16}/><input id="register-company" className="auth-input" type="text" placeholder="Company name" value={registerCompany} onChange={e=>setRegisterCompany(e.target.value)}/></div></div></div>
            <div><label className="auth-label" htmlFor="register-role">Your role</label><div className="auth-input-wrap"><UserRound size={17}/><select id="register-role" className="auth-input bg-transparent" value={authRole} onChange={e=>setAuthRole(e.target.value as Role)}><option>Site Captain</option><option>Project Lead</option><option>Admin</option></select></div></div>
            <div><label className="auth-label" htmlFor="register-password">Create password</label><div className="auth-input-wrap"><LockKeyhole size={17}/><input id="register-password" className="auth-input" type="password" placeholder="Create a password" /></div></div>
            <button type="submit" className="auth-submit mt-2">Create account <ArrowRight size={16}/></button>
          </form>}
          <div className="auth-switch">{authView==="login"?<>New to OnSite? <button onClick={()=>{setAuthView("register");setAuthNotice("");}}>Create an account</button></>:<>Already have an account? <button onClick={()=>{setAuthView("login");setAuthNotice("");}}>Sign in</button></>}</div>
        </div>
        <div className="mt-5 flex items-start gap-2 text-[10px] leading-5 text-gray-500"><ShieldCheck size={15} className="shrink-0 mt-0.5"/><span>Prototype access only. These forms do not verify credentials or create a stored account. Authentication and account security will be implemented for production.</span></div>
        <div className="mt-8 text-center text-[10px] text-gray-400">© 2026 OnSite · Construction project workspace</div>
      </div>
    </section>
  </main>;

  return <div className="app-shell flex">
    <aside className="sidebar min-h-screen flex flex-col fixed top-0 left-0 bottom-0 z-30">
      <div className="px-5 pt-6 pb-5 flex items-center gap-3"><div className="w-9 h-9 rounded-xl bg-[#d9e7dd] text-[#263f34] flex items-center justify-center"><Construction size={20}/></div><div><div className="text-white font-extrabold tracking-wide text-lg" style={{fontFamily:"Manrope"}}>OnSite<span className="text-[#9ab5a3]">.</span></div><div className="text-[9px] tracking-[.15em] text-[#91a198]">PROJECT WORKSPACE</div></div></div>
      <div className="mx-4 p-3 rounded-xl bg-[#22332b] mb-1"><div className="text-[9px] text-[#92a49a] tracking-widest font-bold">ACTIVE PROJECT</div><div className="text-xs text-white font-bold mt-1">Lagos Residential Complex</div><div className="text-[10px] text-[#aab9b0] mt-1 flex items-center gap-1"><MapPin size={10}/> Victoria Island, Lagos</div></div>
      {nav}
      <div className="p-4 border-t border-[#34443c]"><div className="flex items-center gap-2"><div className="w-8 h-8 rounded-full bg-[#dce8df] text-[#385342] flex items-center justify-center text-[10px] font-bold">AB</div><div className="flex-1"><div className="text-xs text-white font-bold">{authName}</div><div className="text-[10px] text-[#93a39a]">{role}</div></div><div className="flex items-center gap-3"><button title="Profile settings" onClick={()=>notify("Profile settings are demo-only.")}><Settings size={15}/></button><button title="Sign out" onClick={()=>{setAuthenticated(false);setAuthView("login");setAuthPassword("");}}><LogOut size={15}/></button></div></div></div>
    </aside>
    <div className="main-area md:ml-[248px]">
      <header className="h-[66px] bg-white border-b border-gray-200 flex items-center justify-between px-5 md:px-8 sticky top-0 z-20">
        <div className="flex items-center gap-3"><button className="md:hidden text-gray-500" onClick={()=>setMobileMenu(!mobileMenu)}><Menu size={20}/></button><div className="text-xs text-gray-400">Lagos Residential Complex <ChevronRight className="inline" size={12}/> <b className="text-gray-700">{pageTitle[screen]}</b></div></div>
        <div className="flex items-center gap-3"><span className="desktop-only text-[10px] text-gray-400">DEMO WORKSPACE</span><div className="relative"><select aria-label="Switch demo role" value={role} onChange={e=>changeRole(e.target.value as Role)} className="border border-gray-200 rounded-lg px-3 py-2 text-xs font-bold bg-white"><option>Site Captain</option><option>Project Lead</option><option>Admin</option></select></div><button onClick={()=>go("inbox")} className="relative p-2 text-gray-500 hover:bg-gray-100 rounded-lg"><Bell size={17}/><span className="absolute top-1 right-1 w-2 h-2 bg-[#c58a45] rounded-full"/></button><div className="w-8 h-8 rounded-full bg-[#e8eee9] text-[#45634f] flex items-center justify-center text-[10px] font-bold desktop-only">AB</div></div>
      </header>
      {mobileMenu&&<div className="md:hidden fixed inset-0 top-[66px] z-40 bg-[#17231f] text-white overflow-auto">{nav}<div className="p-4 text-xs text-gray-400">Viewing as {role}</div></div>}
      <main className="main-content p-6 lg:p-8 max-w-[1500px] mx-auto">{renderContent()}</main>
      <nav className="mobile-nav fixed bottom-0 left-0 right-0 z-30 bg-white border-t border-gray-200 justify-around items-center px-2 py-2">
        {[["today","Today",Home],["feed","Feed",Activity],["capture","Capture",Plus],["inbox","Inbox",Bell],["materials","Store",Package]].map(([key,label,Icon]:any)=><button key={key} onClick={()=>key==="capture"?setCaptureOpen(true):go(key)} className={cn("flex flex-col items-center gap-1 px-2 py-1 text-[9px] font-semibold",screen===key?"text-[#456b56]":"text-gray-400")}><span className={cn(key==="capture"?"rounded-full bg-[#263f34] text-white p-3 -mt-5 shadow-lg":"") }><Icon size={17}/></span>{label}</button>)}
      </nav>
    </div>
    {captureOpen&&<div className="fixed inset-0 z-50 bg-black/40 flex items-end md:items-center justify-center p-0 md:p-4" onClick={()=>setCaptureOpen(false)}><div className="bg-white rounded-t-2xl md:rounded-2xl w-full max-w-lg p-5" onClick={e=>e.stopPropagation()}><div className="flex justify-between items-center mb-4"><div><div className="eyebrow">QUICK ACTIONS</div><h3 className="font-extrabold text-lg">Capture on site</h3></div><button onClick={()=>setCaptureOpen(false)}><X size={18}/></button></div><div className="grid grid-cols-2 gap-3">{[{name:"Daily log",icon:ClipboardList,screen:"log"},{name:"Stage update",icon:ListChecks,screen:"update"},{name:"Materials",icon:Package,screen:"materials"},{name:"Attendance",icon:Users,screen:"attendance"},{name:"Report issue",icon:AlertCircle,screen:"issue"},{name:"Photo or video",icon:Camera,screen:"feed"}].map(a=><button key={a.name} onClick={()=>go(a.screen as Screen)} className="border border-gray-200 rounded-xl p-4 text-left hover:bg-gray-50"><a.icon className="text-[#567563]" size={20}/><div className="font-bold text-xs mt-3">{a.name}</div><div className="text-[10px] text-gray-400 mt-1">Open {a.name.toLowerCase()}</div></button>)}</div></div></div>}
    {modal==="sendback"&&<div className="fixed inset-0 z-[60] bg-black/40 flex items-center justify-center p-4"><div className="bg-white rounded-2xl p-5 w-full max-w-md"><div className="flex justify-between"><h3 className="font-extrabold">Send submission back</h3><button onClick={()=>setModal(null)}><X size={17}/></button></div><p className="text-xs text-gray-500 mt-2">Choose a reason so the Site Captain knows what to fix.</p><div className="grid grid-cols-2 gap-2 mt-4">{["Photo unclear","Wrong work item","Step not finished","Need more photos"].map(r=><button key={r} onClick={()=>setReturnReason(r)} className={cn("rounded-lg border p-2 text-[11px]",returnReason===r?"border-[#6f907b] bg-[#eef4ef]":"border-gray-200")}>{r}</button>)}</div><textarea className="field mt-3" placeholder="Additional note (optional)" value={returnNote} onChange={e=>setReturnNote(e.target.value)}/><div className="flex justify-end gap-2 mt-4"><Button kind="secondary" onClick={()=>setModal(null)}>Cancel</Button><Button kind="danger" onClick={sendBack}>Send back</Button></div></div></div>}
    {toast&&<div role="status" className="fixed bottom-20 md:bottom-6 right-5 z-[80] bg-[#20382c] text-white rounded-xl px-4 py-3 text-xs shadow-xl flex items-center gap-2"><CheckCircle2 size={15}/>{toast}</div>}
    <div className="fixed bottom-2 left-2 text-[8px] text-gray-400 opacity-50 pointer-events-none hidden md:block">OnSite prototype · Demo data only</div>
  </div>;
}
